pub fn check_limits(limits: &Limits) -> Result<(), Problem> {
    for ((value, ceiling), path) in limits.values().as_slice().iter().zip(CEILING_VALUES).zip(LIMIT_PATHS) {
        if value > ceiling {
            return Err(path.problem(skein_codec::Reason::Bound));
        }
    }
    Ok(())
}

